<?php
require_once __DIR__.'/../includes/layout.php';$u=require_login('admin');
$stats=[];foreach(['users'=>'SELECT COUNT(*) FROM users','students'=>"SELECT COUNT(*) FROM users WHERE role='student'",'recruiters'=>"SELECT COUNT(*) FROM users WHERE role='recruiter'",'offers'=>'SELECT COUNT(*) FROM offers','applications'=>'SELECT COUNT(*) FROM applications'] as $key=>$sql)$stats[$key]=db()->query($sql)->fetchColumn();
